<script setup>
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { Button,Empty } from 'ant-design-vue'
import { useDocumentRead } from './documentState.js'
import { imageObjectUrl,tableHighlights } from './documentModel.js'
import { useRoute } from 'vue-router'
import ReadState from './ReadState.vue'
import { remembered,useBrowseMemory } from './browseMemory.js'
import Facts from './Facts.vue'
const props=defineProps({documentId:String,memory:{type:Object,default:()=>({})}}),route=useRoute()
const snapshot=useDocumentRead('snapshot'),diagnostic=useDocumentRead('diagnostic'),pages=useDocumentRead('pages'),page=useDocumentRead('page'),imageState=useDocumentRead('content')
defineEmits(['return-explorer'])
const mode=remembered(props.memory,'mode','overview'),pageNo=remembered(props.memory,'pageNo',''),overlayType=remembered(props.memory,'overlayType',''),region=remembered(props.memory,'region',''),image=ref('');
if(route.query.locatePage)mode.value='locator'
const restoreScroll=useBrowseMemory(props.memory,{mode,pageNo,overlayType,region});let generation=0,disposed=false
const taskPayload=()=>({documentId:props.documentId,parseTaskId:snapshot.data.value?.parseTaskId || route.query.parseTaskId || undefined})
async function load(){await snapshot.read({documentId:props.documentId,parseTaskId:typeof route.query.parseTaskId==='string'?route.query.parseTaskId:undefined,indexTaskId:typeof route.query.indexTaskId==='string'?route.query.indexTaskId:undefined,...tableHighlights(route.query)});if(!disposed&&mode.value!=='overview')await readMode();restoreScroll()}
async function readMode(){if(mode.value==='diagnostic')diagnostic.read(taskPayload());if(mode.value==='locator'){await pages.read(taskPayload());const target=route.query.locatePage||pageNo.value;if(target){const previous=region.value;pageNo.value=String(target);await selectPage();region.value=String(route.query.locateOverlay||previous||'')}}}
async function selectPage(){const owner=++generation;region.value='';if(image.value)URL.revokeObjectURL(image.value);image.value='';await page.read({...taskPayload(),pageNo:pageNo.value});if(disposed||owner!==generation)return;const artifactId=page.data.value?.page?.pageImageArtifactId;if(artifactId){await imageState.read({documentId:props.documentId,taskId:taskPayload().parseTaskId,artifactId});if(!disposed&&owner===generation)image.value=imageObjectUrl(imageState.data.value)}}
const overlays=computed(()=>(page.data.value?.page?.overlays||[]).filter(row=>!overlayType.value||row.type===overlayType.value))
const types=computed(()=>[...new Set((page.data.value?.page?.overlays||[]).map(row=>row.type).filter(Boolean))])
function bbox(row){const values=[row.leftRatio,row.topRatio,row.widthRatio,row.heightRatio].map(Number);if(values.some(v=>!Number.isFinite(v)||v<0)||values[2]<=0||values[3]<=0)return null;return {left:`${values[0]*100}%`,top:`${values[1]*100}%`,width:`${values[2]*100}%`,height:`${values[3]*100}%`}}
const selected=computed(()=>overlays.value.find(row=>row.overlayId===region.value))
watch(()=>JSON.stringify(tableHighlights(route.query)),()=>{mode.value='overview';load()});onMounted(load);onBeforeUnmount(()=>{disposed=true;generation++;if(image.value)URL.revokeObjectURL(image.value)})
</script>
<template><section class="admin-next-doc-panel"><div class="admin-next-doc-row"><h2>解析工作台</h2><Button v-if="route.query.browseFrom==='explorer'" @click="$emit('return-explorer')">返回产物与关系</Button><Button :disabled="snapshot.loading.value" @click="load">刷新快照</Button></div><ReadState :state="snapshot" label="RAG 快照" @retry="load" /><div class="admin-next-doc-toolbar"><label for="parse-mode" class="chat-next-sr-only">解析视图</label><select id="parse-mode" v-model="mode" @change="readMode"><option value="overview">处理概览</option><option value="diagnostic">质量诊断</option><option value="locator">页面定位</option></select></div><template v-if="mode==='overview'&&snapshot.data.value"><div class="admin-next-doc-metrics"><div v-for="item in snapshot.data.value.metrics || []" :key="item.label"><span>{{ item.label }}</span><strong>{{ item.value ?? '—' }}</strong><small>{{ item.hint }}</small></div></div><ol class="admin-next-doc-items"><li v-for="item in snapshot.data.value.pipelineStages || []" :key="item.code"><strong>{{ item.title }}</strong><span>{{ item.statusText }}</span><p>{{ item.description }}</p></li></ol><details v-for="key in ['parserTrace','parseBlocks','structureNodes','parentBlocks','chunks','kgEntities','kgRelations','kgCommunities','kgGraph','raptorQuality','buildLogs']" :key="key"><summary>{{ {parserTrace:'解析轨迹',parseBlocks:'解析块样本',structureNodes:'结构节点样本',parentBlocks:'父块样本',chunks:'子块样本',kgEntities:'实体样本',kgRelations:'关系样本',kgCommunities:'社区样本',kgGraph:'图谱质量与证据',raptorQuality:'RAPTOR 质量',buildLogs:'构建日志'}[key] }}</summary><Facts :value="snapshot.data.value[key]" /></details><section v-for="table in snapshot.data.value.tables || []" :key="table.tableId" class="admin-next-doc-table-block"><h3>{{ table.title || `表格 ${table.tableNo}` }}</h3><p class="admin-next-doc-muted">{{ table.sectionPath }} · 表格 ID {{ table.tableId }} · 接口返回样本</p><div class="admin-next-doc-scroll" role="region" :aria-label="`表格 ${table.tableNo}`" tabindex="0"><table><thead><tr><th v-for="col in table.columns || []" :key="col.columnId" scope="col">{{ col.columnName }}</th></tr></thead><tbody><tr v-for="row in table.rows || []" :key="row.rowId"><td v-for="(value,i) in row.cells || []" :key="i" :class="{'admin-next-doc-highlight':(tableHighlights(route.query).highlightRowNos||[]).includes(String(row.rowNo))||(tableHighlights(route.query).highlightColumnNames||[]).includes(table.columns?.[i]?.columnName)||(tableHighlights(route.query).highlightCellCoordinates||[]).includes(`${row.rowNo}:${i+1}`)}">{{ value }}</td></tr></tbody></table></div></section><p v-if="snapshot.data.value.runtimeObservationNote" class="admin-next-doc-muted">{{ snapshot.data.value.runtimeObservationNote }}</p></template>
<template v-if="mode==='diagnostic'"><ReadState :state="diagnostic" label="质量诊断" @retry="readMode" /><Facts v-if="diagnostic.data.value" :value="diagnostic.data.value.trace" :labels="{providerName:'解析器',providerVersion:'版本',pageCount:'页数',ocrPageCount:'OCR 页数',warningCount:'告警数',warnings:'告警',bboxBlockCoverage:'块定位覆盖率',tableCellBboxCoverage:'表格单元格定位覆盖率',elapsedMs:'耗时（ms）'}" /></template>
<template v-if="mode==='locator'"><ReadState :state="pages" label="页面索引" @retry="readMode" /><div class="admin-next-doc-toolbar"><label for="overlay-page">页码</label><select id="overlay-page" v-model="pageNo" @change="selectPage"><option value="">请选择页面</option><option v-for="item in pages.data.value?.pages || []" :key="item.pageNo" :value="String(item.pageNo)">{{ item.displayPageNo || item.pageNo }}</option></select><label for="overlay-type">图层</label><select id="overlay-type" v-model="overlayType"><option value="">全部图层</option><option v-for="type in types" :key="type">{{ type }}</option></select></div><ReadState :state="page" label="页面定位" @retry="selectPage" /><ReadState :state="imageState" label="页面图片" @retry="selectPage" /><Empty v-if="pages.data.value&&!pages.data.value.pages?.length" description="暂无页面定位信息" /><div v-if="image" class="admin-next-doc-page-image"><img :src="image" :alt="`第 ${pageNo} 页`" /><template v-for="row in overlays" :key="row.overlayId"><button v-if="bbox(row)" type="button" :aria-label="`定位 ${row.label || row.overlayId}`" :style="bbox(row)" :class="{'is-selected':region===row.overlayId}" @click="region=row.overlayId"></button></template></div><p v-else-if="page.data.value" class="admin-next-doc-muted">原图未提供或无法预览，仍可查看定位数据。</p><ul class="admin-next-doc-items"><li v-for="row in overlays" :key="row.overlayId"><Button @click="region=row.overlayId">{{ row.label || row.overlayId }}</Button><span>{{ row.sectionPath }} · {{ row.type }}</span></li></ul><Facts v-if="selected" :value="selected" /></template></section></template>
